-- Voice notes on applet pages (docs/voice-notes.md). Recorded by the phone,
-- anchored to a view (and step) ID so they survive layout changes. Audio
-- lives in object storage; the row holds key, type, size and hash.
CREATE TABLE voice_notes (
  -- Generated by the glasses, so a retried start is idempotent.
  id                 uuid PRIMARY KEY,
  owner_id           uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  project_id         uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  release_id         uuid REFERENCES releases(id) ON DELETE SET NULL,
  device_id          uuid REFERENCES devices(id) ON DELETE SET NULL,
  view_id            text NOT NULL CHECK (view_id ~ '^[a-z][a-z0-9_]{0,39}$'),
  step_id            text CHECK (step_id ~ '^[a-z][a-z0-9_]{0,39}$'),
  page_label         text NOT NULL CHECK (length(page_label) BETWEEN 1 AND 120),
  note_label         text CHECK (length(note_label) <= 60),
  -- describeState() of the applet when recording started ("Rows: 14").
  state_snapshot     jsonb,
  -- starting: glasses asked, phone not confirmed; recording: phone confirmed;
  -- uploaded: audio stored, transcription queued; transcribing; transcribed;
  -- failed: transcription failed (audio kept); discarded: nothing worth keeping.
  status             text NOT NULL DEFAULT 'starting'
                     CHECK (status IN ('starting', 'recording', 'uploaded', 'transcribing', 'transcribed', 'failed', 'discarded')),
  end_reason         text CHECK (end_reason IN ('phrase', 'band', 'voice', 'timeout', 'disconnect', 'interrupted', 'phone', 'too_short')),
  started_at         timestamptz NOT NULL DEFAULT now(),
  ended_at           timestamptz,
  duration_ms        integer CHECK (duration_ms >= 0),
  audio_key          text UNIQUE,
  audio_media_type   text,
  audio_sha256       text CHECK (audio_sha256 ~ '^[0-9a-f]{64}$'),
  audio_bytes        bigint CHECK (audio_bytes > 0),
  transcript         text CHECK (length(transcript) <= 20000),
  transcript_edited  boolean NOT NULL DEFAULT false,
  transcript_model   text,
  -- Audio hash the current transcript was made from (re-uploads re-transcribe).
  transcribed_sha256 text CHECK (transcribed_sha256 ~ '^[0-9a-f]{64}$'),
  language           text NOT NULL DEFAULT 'en' CHECK (language ~ '^[a-z]{2}$'),
  error              jsonb,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CHECK ((audio_key IS NULL) = (audio_sha256 IS NULL)),
  CHECK (status NOT IN ('uploaded', 'transcribing', 'transcribed', 'failed') OR audio_key IS NOT NULL)
);
CREATE INDEX voice_notes_project ON voice_notes (owner_id, project_id, started_at DESC);

ALTER TABLE jobs DROP CONSTRAINT jobs_kind_check;
ALTER TABLE jobs ADD CONSTRAINT jobs_kind_check
  CHECK (kind IN ('prepare_upload', 'generate_revision', 'package_release', 'transcribe_voice_note'));
